// =====================================================================
//  REGLAS DE NEGOCIO · PRÉSTAMO DE RECURSOS TECNOLÓGICOS
//  Para cambiar una regla, modifica estas constantes o la condición
//  correspondiente más abajo (cada regla está marcada con su código).
// =====================================================================
const MAX_DIAS_PRESTAMO = 3; // RN-06
const MAX_PRESTAMOS_ACTIVOS_POR_PERSONA = 2; // RN-07

// ---------------------------------------------------------------------
//  Utilidades de validación
// ---------------------------------------------------------------------
const texto = (valor) => (valor === undefined || valor === null ? '' : String(valor).trim());
const numero = (valor) => (texto(valor) === '' ? NaN : Number(valor));
const esEnteroPositivo = (valor) => Number.isInteger(valor) && valor > 0;
const esFecha = (valor) => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) return false;
  const fecha = new Date(`${valor}T00:00:00Z`);
  return !Number.isNaN(fecha.getTime()) && fecha.toISOString().slice(0, 10) === valor;
};
const esHora = (valor) => /^([01]\d|2[0-3]):[0-5]\d$/.test(valor);
const esFechaHora = (valor) => /^\d{4}-\d{2}-\d{2}T([01]\d|2[0-3]):[0-5]\d$/.test(valor) && esFecha(valor.slice(0, 10));
const aMinutos = (hora) => Number(hora.slice(0, 2)) * 60 + Number(hora.slice(3, 5));
// Suma días a "AAAA-MM-DDTHH:MM" (hora local del campus, sin zona horaria)
const sumarDias = (fechaHora, dias) => {
  const fecha = new Date(`${fechaHora}:00Z`);
  fecha.setUTCDate(fecha.getUTCDate() + dias);
  return fecha.toISOString().slice(0, 16);
};
const respuestaError = (status, code, message, details = []) => [
  { json: { ok: false, status, body: { ok: false, error: { code, message, details } } } },
];
const cuerpo = $('POST /prestamos').first().json.body ?? {};
const ctx = $input.first().json;

// 1. Datos de entrada --------------------------------------------------
const prestamo = {
  recurso_id: numero(cuerpo.recurso_id),
  solicitante: texto(cuerpo.solicitante),
  // Acepta "AAAA-MM-DDTHH:MM" (input datetime-local) o con espacio
  fecha_limite: texto(cuerpo.fecha_limite).replace(' ', 'T').slice(0, 16),
};

const datosInvalidos = [];
if (!esEnteroPositivo(prestamo.recurso_id)) datosInvalidos.push('Selecciona un recurso válido.');
if (!prestamo.solicitante || prestamo.solicitante.length > 120) datosInvalidos.push('Indica quién solicita el préstamo.');
if (!esFechaHora(prestamo.fecha_limite)) datosInvalidos.push('La fecha de devolución debe tener el formato AAAA-MM-DD HH:MM.');
if (datosInvalidos.length) {
  return respuestaError(400, 'DATOS_INVALIDOS', datosInvalidos[0], datosInvalidos.map((mensaje) => ({ regla: 'DATOS', mensaje })));
}

const recurso = ctx.recurso;
if (!recurso) return respuestaError(404, 'RECURSO_NO_ENCONTRADO', 'El recurso seleccionado no existe.');

// 2. Reglas de negocio -------------------------------------------------
const incumplidas = [];
const regla = (cumple, codigo, mensaje) => {
  if (!cumple) incumplidas.push({ regla: codigo, mensaje });
};

// RN-05 Solo se prestan recursos disponibles (no prestados, en mantenimiento ni de baja)
regla(
  recurso.estado === 'disponible',
  'RN-05',
  `${recurso.nombre} (${recurso.codigo}) no está disponible: estado "${recurso.estado}"${recurso.motivo_estado ? ` (${recurso.motivo_estado})` : ''}.`,
);

// RN-06 Plazo: devolución en el futuro y como máximo MAX_DIAS_PRESTAMO días
const limiteMaximo = sumarDias(ctx.ahora, MAX_DIAS_PRESTAMO);
regla(prestamo.fecha_limite > ctx.ahora, 'RN-06', 'La fecha de devolución debe ser posterior al momento actual.');
regla(
  prestamo.fecha_limite <= limiteMaximo,
  'RN-06',
  `Un préstamo dura máximo ${MAX_DIAS_PRESTAMO} días: la devolución debe ser a más tardar el ${limiteMaximo.replace('T', ' ')}.`,
);

// RN-07 Cupo: sin préstamos vencidos y con un máximo de préstamos activos
const activos = ctx.prestamos_del_solicitante;
const vencidos = activos.filter((p) => p.vencido);
regla(
  vencidos.length === 0,
  'RN-07',
  `${prestamo.solicitante} tiene préstamos vencidos sin devolver (${vencidos.map((p) => p.recurso_codigo).join(', ')}).`,
);
regla(
  activos.length < MAX_PRESTAMOS_ACTIVOS_POR_PERSONA,
  'RN-07',
  `${prestamo.solicitante} ya tiene ${activos.length} préstamo(s) activo(s); el máximo es ${MAX_PRESTAMOS_ACTIVOS_POR_PERSONA}.`,
);

if (incumplidas.length) {
  return respuestaError(422, 'REGLA_DE_NEGOCIO', incumplidas[0].mensaje, incumplidas);
}

return [{ json: { ok: true, ...prestamo } }];

